svg.script:
function showLabel(id, name, cx, cy) {
  var g = document.getElementById('labelPopup');
  var bg = document.getElementById('labelBg');
  var txt = document.getElementById('labelText');
  txt.textContent = name;
  var w = 70 + name.length * 19;
  bg.setAttribute('width', w);
  bg.setAttribute('x', -w/2);
  g.setAttribute('transform', 'translate(' + cx + ',' + (cy - 120) + ')');
  g.setAttribute('opacity','1');
  g.classList.remove('popAnim');
  void g.offsetWidth;
  g.classList.add('popAnim');
}
